function Info($p){ if(-not(Test-Path $p)){ Write-Host "$p : MISSING"; return } $i=Get-Item $p; Write-Host "$p"; Write-Host "  LinkType=$($i.LinkType) Target=[$($i.Target)] IsDir=$($i.PSIsContainer)" }
Info 'D:\repository\门户'
Info 'D:\repository\门户H5'
Write-Host "=== 门户 top-level (first 30) ==="
if(Test-Path 'D:\repository\门户'){ Get-ChildItem 'D:\repository\门户' | Select-Object -First 30 Name }
Write-Host "=== git remotes: 门户H5 ==="
if(Test-Path 'D:\repository\门户H5\.git'){ git -C 'D:\repository\门户H5' remote -v; git -C 'D:\repository\门户H5' branch --show-current } else { 'no .git in 门户H5' }
Write-Host "=== git remotes: 门户 ==="
if(Test-Path 'D:\repository\门户\.git'){ git -C 'D:\repository\门户' remote -v; git -C 'D:\repository\门户' branch --show-current } else { 'no .git in 门户' }

$se='D:\nginx\conf\sites-enabled\门户.conf'
$sa='D:\nginx\conf\sites-available\门户'
foreach($p in @($se,$sa)){
  $i=Get-Item $p -ErrorAction SilentlyContinue
  if($i){ Write-Host "$p :: LinkType=$($i.LinkType) Target=[$($i.Target)] Length=$($i.Length) LastWrite=$($i.LastWriteTime)" } else { Write-Host "$p :: MISSING" }
}
# content equality
if((Test-Path $se)-and(Test-Path $sa)){
  $a=Get-Content $se -Raw; $b=Get-Content $sa -Raw
  Write-Host "Contents identical: $($a.Equals($b))"
}
Write-Host "=== nginx.conf sites include ==="
Get-Content 'D:\nginx\conf\nginx.conf' | Select-String -Pattern 'sites-enabled|sites-available|include' | Select-Object -First 20

