tool_input.command:
$root='D:\repository\门户H5'
Write-Host "=== build.log tail ==="; if(Test-Path $root\build.log){ Get-Content $root\build.log -Tail 15 }
Write-Host "=== 门户H5\dist fresh files ==="; if(Test-Path $root\dist){ Get-ChildItem $root\dist | Select-Object Name,LastWriteTime | Format-Table -AutoSize; $ih=Get-Item $root\dist\index.html; Write-Host "index.html LastWrite=$($ih.LastWriteTime)" }

$new='D:\repository\门户H5\dist\index.html'
$old='D:\repository\门户\dist\index.html'
try {
  $r = Invoke-WebRequest -Uri http://localhost:8092/ -UseBasicParsing
  Write-Host "StatusCode: $($r.StatusCode)  Bytes: $($r.Content.Length)"
  $served = $r.Content
  # distinctive tokens: title + first script src + first css link
  $title = if($served -match '<title>(.*?)</title>'){ $matches[1] } else { '(no title)' }
  Write-Host "served <title>: $title"
  $script = if($served -match '<script[^>]+src="([^"]+)"'){ $matches[1] } else { '(no script)' }
  Write-Host "served first script: $script"
  # does that script asset exist in 门户H5/dist?
  if($script){
    $rel = $script.TrimStart('/')
    Write-Host "asset in 门户H5/dist: $(if(Test-Path (Join-Path 'D:\repository\门户H5\dist' $rel)){'YES'}else{'NO'})"
    Write-Host "asset in 门户/dist:   $(if(Test-Path (Join-Path 'D:\repository\门户\dist' $rel)){'YES'}else{'NO'})"
  }
  # hash compare
  $servedHash=(Get-FileHash -InputStream ([System.IO.MemoryStream]::new([System.Text.Encoding]::UTF8.GetBytes($served))) -Algorithm MD5).Hash
  $newHash=(Get-FileHash $new -Algorithm MD5).Hash
  $oldHash=if(Test-Path $old){(Get-FileHash $old -Algorithm MD5).Hash}else{'OLD_MISSING'}
  Write-Host "served MD5=$servedHash"; Write-Host "门户H5 MD5=$newHash match=$($servedHash -eq $newHash)"; Write-Host "门户   MD5=$oldHash match=$($servedHash -eq $oldHash)"
} catch { Write-Host "ERR: $_" }
